import timelineJson from "./timeline.json";

/**
 * GermanElection video: design tokens + timeline helpers.
 *
 * timeline.json is generated by scripts/german-election/build_voice.py from the narration.
 * Every visual cue below is looked up from it (never hard-coded), so re-generating the
 * voice-over keeps animation, subtitles and sound effects in sync automatically.
 */

export const COLORS = {
  paper: "#F4F1EA",
  paperDeep: "#E8E2D5",
  card: "#FFFFFF",
  ink: "#16161A",
  inkSoft: "#4A4A55",
  muted: "#A39E92",
  line: "#D9D2C3",
  // German flag
  black: "#000000",
  red: "#DD0000",
  gold: "#FFCE00",
  // Readable variants on the light background
  goldDeep: "#D9A400",
  redSoft: "#F3C9C4",
  seatGold: "#EDB200",
  barGrey: "#8A8578",
  barOut: "#D6D0C4",
  skin: "#E8B996",
  skinShade: "#D29F7C",
  hairGrey: "#B9B4AA",
  hairDark: "#3B3330",
  white: "#FFFFFF",
} as const;

export const FONT = "'Inter Variable', Inter, system-ui, sans-serif";

/** Vertical 9:16 layout (px). Keeps clear of TikTok's top bar, side buttons and caption area. */
export const LAYOUT = {
  width: 1080,
  height: 1920,
  marginX: 120,
  headerTop: 170,
  stageTop: 340,
  subtitleCenterY: 1395,
} as const;

export type SceneId = "title" | "votes" | "bundestag" | "chancellor" | "president";
export type SentenceId =
  | "hook"
  | "twoVotes"
  | "firstVote"
  | "secondVote"
  | "threshold"
  | "seats"
  | "elect"
  | "merz"
  | "convention"
  | "steinmeier";

export type Word = { text: string; hl: boolean; line: number; from: number; to: number };
export type Sentence = { scene: SceneId; from: number; to: number; words: Word[] };

export const TIMELINE = timelineJson as {
  fps: number;
  durationInFrames: number;
  voice: string;
  scenes: Record<SceneId, { from: number; durationInFrames: number }>;
  sentences: Record<SentenceId, Sentence>;
};

export const SCENE_ORDER: SceneId[] = ["title", "votes", "bundestag", "chancellor", "president"];
export const SENTENCE_ORDER = Object.keys(TIMELINE.sentences) as SentenceId[];

export const sceneOf = (id: SceneId) => TIMELINE.scenes[id];
export const sceneEnd = (id: SceneId) => sceneOf(id).from + sceneOf(id).durationInFrames;

const bare = (s: string) => s.replace(/[^\p{L}\p{N}%-]/gu, "").toLowerCase();

/**
 * Global frame at which a narration word starts.
 * `word` is the on-screen word ("630", "Chancellor") or its index; defaults to the first word.
 */
export const cue = (sentence: SentenceId, word: string | number = 0): number => {
  const words = TIMELINE.sentences[sentence].words;
  const i = typeof word === "number" ? word : words.findIndex((w) => bare(w.text) === bare(word));
  if (i < 0 || i >= words.length) {
    throw new Error(`No word "${word}" in sentence "${sentence}"`);
  }
  return words[i].from;
};

/** Global frame at which a sentence finishes. */
export const cueEnd = (sentence: SentenceId): number => TIMELINE.sentences[sentence].to;

/** Same as cue(), but relative to the start of a scene (for use inside that scene's Sequence). */
export const localCue =
  (scene: SceneId) =>
  (sentence: SentenceId, word: string | number = 0): number =>
    cue(sentence, word) - sceneOf(scene).from;

/** Frames each scene keeps rendering after its end while it animates out (overlaps the next one). */
export const EXIT_FRAMES = 3;
